WITH docs AS (SELECT value AS doc FROM jsonb_array_elements($authored$[{"case_key":"bank-legal-2026-001","title":"Заповедный грант","category":"Региональные финансы","situation":"В Адыгее грант экотуристической фирме предложено перечислить до отбора получателей: сезон начинается завтра, а критерии комиссии ещё не опубликованы.\n\nВ учебном досье указаны 2,4 млн ₽ поддержки и три потенциальных получателя. Одна компания уже заказала экскурсионные автобусы, две другие не знают о конкурсе. Срок открытия маршрута не совпадает со сроком обязательного оформления расхода. В распоряжении участника есть проект порядка, письмо предпринимателя и календарь сезона; нужно выбрать действие до передачи платёжного поручения.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.","seriousness":"serious","audience":"all","allowed_roles":["глава","муницип","министр финансов"],"decision_options":["Опубликовать порядок отбора и провести его до перечисления средств, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Перечислить грант сегодня, а критерии отбора оформить после сезона, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Опубликовать порядок отбора и провести его до перечисления средств. Основание: БК РФ, статья 78. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Опубликовать порядок отбора и провести его до перечисления средств. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"БК РФ, статья 78 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.004,"expenditure":15}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статья 78 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.004,"expenditure":15}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статья 78 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.004,"expenditure":15}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статья 78 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.004,"expenditure":15}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Перечислить грант сегодня, а критерии отбора оформить после сезона. Надлежащий шаг: Опубликовать порядок отбора и провести его до перечисления средств. Основание: БК РФ, статья 78. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Перечислить грант сегодня, а критерии отбора оформить после сезона. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, статья 78 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":-0.006,"expenditure":45}}]},"comic_scene":{"scene_id":"scene-051","title":"Заповедный грант","case_key":"bank-legal-2026-001","format":"animated-svg","version":4,"alt":"Заповедный грант: участники изучают гостиничный учёт и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Заповедный грант»: В Адыгее грант экотуристической фирме предложено перечислить до отбора получателей: сезон начинается завтра, а критерии комиссии ещё не опубликованы.","region_code":"01","region_name":"Республика Адыгея"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, статья 78. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-002","title":"Заводская льгота","category":"Региональные финансы","situation":"В Башкортостане губернатор обещает конкретному заводу освободить прибыль от налога письмом администрации. Регионального закона о льготе нет.\n\nДиректор завода показывает обещание сохранить 70 рабочих мест и просит налогового инспектора применить письмо к ближайшему авансовому платежу. В налоговых регистрах прибыль уже определена. Юрист администрации не нашёл опубликованного акта с условиями льготы. До срока платежа осталось пять дней, а депутаты готовы рассмотреть предложение на заседании через неделю.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Подготовить законную категориальную меру и оценку выпадающих доходов, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Освободить один завод от налога письмом губернатора, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Подготовить законную категориальную меру и оценку выпадающих доходов. Основание: НК РФ, статьи 12, 56. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Стратегический критерий: Сохранение законной поддержки промышленного сектора без произвольной льготы. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Подготовить законную категориальную меру и оценку выпадающих доходов. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":"Сохранение законной поддержки промышленного сектора без произвольной льготы.","legal_basis":"НК РФ, статьи 12, 56 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.005,"expenditure":16}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Сохранение законной поддержки промышленного сектора без произвольной льготы.","legal_basis":"НК РФ, статьи 12, 56 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.005,"expenditure":16}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Сохранение законной поддержки промышленного сектора без произвольной льготы.","legal_basis":"НК РФ, статьи 12, 56 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.005,"expenditure":16}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":"Сохранение законной поддержки промышленного сектора без произвольной льготы.","legal_basis":"НК РФ, статьи 12, 56 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.005,"expenditure":16}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Освободить один завод от налога письмом губернатора. Надлежащий шаг: Подготовить законную категориальную меру и оценку выпадающих доходов. Основание: НК РФ, статьи 12, 56. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Освободить один завод от налога письмом губернатора. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"НК РФ, статьи 12, 56 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":-0.007,"expenditure":46}}]},"comic_scene":{"scene_id":"scene-052","title":"Заводская льгота","case_key":"bank-legal-2026-002","format":"animated-svg","version":4,"alt":"Заводская льгота: участники изучают целевой объект и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Заводская льгота»: В Башкортостане губернатор обещает конкретному заводу освободить прибыль от налога письмом администрации. Регионального закона о льготе нет.","region_code":"02","region_name":"Республика Башкортостан"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. НК РФ, статьи 12, 56. https://www.nalog.gov.ru/rn77/taxation/tax_legislation/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-003","title":"Байкальское софинансирование","category":"Региональные финансы","situation":"В Бурятии федеральная субсидия на очистные требует регионального софинансирования. В проекте бюджета этой строки нет, подрядчик просит аванс.\n\nВ учебном расчёте строительство стоит 90 млн ₽, из которых 18 млн ₽ должен предоставить регион. Федеральное соглашение содержит сроки ввода объекта и условия перечисления средств. Подрядчик подготовил площадку, но казначейство не получило подтверждения ассигнований. Участнику переданы проект соглашения, смета и выдержка из регионального бюджета; решение требуется до подписания авансового платежа.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Обеспечить софинансирование и бюджетные полномочия до заключения обязательства, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Выдать аванс на очистные, не меняя проект бюджета, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Обеспечить софинансирование и бюджетные полномочия до заключения обязательства. Основание: БК РФ, статьи 38, 139. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Обеспечить софинансирование и бюджетные полномочия до заключения обязательства. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"БК РФ, статьи 38, 139 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":17}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статьи 38, 139 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":17}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статьи 38, 139 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":17}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статьи 38, 139 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":17}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Выдать аванс на очистные, не меняя проект бюджета. Надлежащий шаг: Обеспечить софинансирование и бюджетные полномочия до заключения обязательства. Основание: БК РФ, статьи 38, 139. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Выдать аванс на очистные, не меняя проект бюджета. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, статьи 38, 139 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":-0.008,"expenditure":47}}]},"comic_scene":{"scene_id":"scene-053","title":"Байкальское софинансирование","case_key":"bank-legal-2026-003","format":"animated-svg","version":4,"alt":"Байкальское софинансирование: участники изучают целевой объект и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Байкальское софинансирование»: В Бурятии федеральная субсидия на очистные требует регионального софинансирования. В проекте бюджета этой строки нет, подрядчик просит аванс.","region_code":"03","region_name":"Республика Бурятия"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, статьи 38, 139. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-004","title":"Курортные дни","category":"Региональные финансы","situation":"В Республике Алтай муниципальный совет предлагает туристический налог 5% уже в 2026 году. Отель включил сумму в новый прайс.\n\nСовет обсуждает проект решения на очередной сессии, а владельцы гостиниц уже уведомили гостей о новых ценах. В таблице администратора смешаны предельная ставка соответствующего года и ставка будущего периода. Один турист забронировал номер заранее и требует объяснить изменение стоимости. Участнику доступны календарь введения налога, проект муниципального акта и расчёт на одну ночёвку.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.","seriousness":"serious","audience":"all","allowed_roles":["глава","муницип","министр финансов"],"decision_options":["Привести ставку 2026 года к допустимому пределу и исправить расчёты, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Оставить туристическую ставку 5% в 2026 году, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Привести ставку 2026 года к допустимому пределу и исправить расчёты. Основание: НК РФ, глава 33.1. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Привести ставку 2026 года к допустимому пределу и исправить расчёты. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"НК РФ, глава 33.1 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.007,"expenditure":18}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, глава 33.1 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.007,"expenditure":18}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, глава 33.1 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.007,"expenditure":18}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, глава 33.1 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.007,"expenditure":18}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Оставить туристическую ставку 5% в 2026 году. Надлежащий шаг: Привести ставку 2026 года к допустимому пределу и исправить расчёты. Основание: НК РФ, глава 33.1. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Оставить туристическую ставку 5% в 2026 году. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"legal_basis":"НК РФ, глава 33.1 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":-0.009000000000000001,"expenditure":48}}]},"comic_scene":{"scene_id":"scene-054","title":"Курортные дни","case_key":"bank-legal-2026-004","format":"animated-svg","version":4,"alt":"Курортные дни: участники изучают гостиничный учёт и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Курортные дни»: В Республике Алтай муниципальный совет предлагает туристический налог 5% уже в 2026 году. Отель включил сумму в новый прайс.","region_code":"04","region_name":"Республика Алтай"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. НК РФ, глава 33.1. https://www.nalog.gov.ru/rn77/taxation/tax_legislation/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-005","title":"Целевой водопровод","category":"Региональные финансы","situation":"В Дагестане субвенцию на переданное полномочие хотят направить на городской фонтан. Администрация ссылается на одинаковую водную тематику.\n\nСредства поступили с кодом целевого назначения, отдельным отчётом и сроком выполнения переданного полномочия. Проект фонтана стоит 6 млн ₽ и поддерживается частью жителей, но отсутствует в соглашении о субвенции. Бухгалтер предлагает поменять название расхода в заявке, сохранив его содержание. Участник проверяет соглашение, смету и объём ещё неисполненных обязательств переданных полномочий.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Сохранить целевое назначение субвенции и найти иной источник для фонтана, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Потратить субвенцию на фонтан, поскольку обе цели связаны с водой, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Сохранить целевое назначение субвенции и найти иной источник для фонтана. Основание: БК РФ, статьи 38, 140. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Сохранить целевое назначение субвенции и найти иной источник для фонтана. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"БК РФ, статьи 38, 140 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.008,"expenditure":19}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статьи 38, 140 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.008,"expenditure":19}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статьи 38, 140 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.008,"expenditure":19}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статьи 38, 140 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.008,"expenditure":19}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Потратить субвенцию на фонтан, поскольку обе цели связаны с водой. Надлежащий шаг: Сохранить целевое назначение субвенции и найти иной источник для фонтана. Основание: БК РФ, статьи 38, 140. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Потратить субвенцию на фонтан, поскольку обе цели связаны с водой. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, статьи 38, 140 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":-0.01,"expenditure":49}}]},"comic_scene":{"scene_id":"scene-055","title":"Целевой водопровод","case_key":"bank-legal-2026-005","format":"animated-svg","version":4,"alt":"Целевой водопровод: участники изучают целевой объект и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Целевой водопровод»: В Дагестане субвенцию на переданное полномочие хотят направить на городской фонтан. Администрация ссылается на одинаковую водную тематику.","region_code":"05","region_name":"Республика Дагестан"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, статьи 38, 140. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-006","title":"Смета школы","category":"Региональные финансы","situation":"Казённая школа Ингушетии принимает обязательство на ремонт сверх доведённых лимитов. Директор обещает закрыть разницу будущей платной кружковой работой.\n\nПо учебной смете школе доведено 3 млн ₽, а подрядчик предлагает договор на 4,2 млн ₽. Акт обследования подтверждает необходимость ремонта, однако собственные доходы следующего года ещё не получены. Платёжный график предусматривает аванс до начала работ. На столе у участника лежат смета, лимиты и договор; директор просит решить вопрос до окончания срока предложения подрядчика.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Увязать обязательство со сметой и лимитами бюджетных обязательств, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Подписать школьный контракт сверх лимитов в расчёте на доход кружков, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Увязать обязательство со сметой и лимитами бюджетных обязательств. Основание: БК РФ, статьи 161, 219. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Увязать обязательство со сметой и лимитами бюджетных обязательств. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"БК РФ, статьи 161, 219 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.009000000000000001,"expenditure":20}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статьи 161, 219 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.009000000000000001,"expenditure":20}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статьи 161, 219 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.009000000000000001,"expenditure":20}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статьи 161, 219 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.009000000000000001,"expenditure":20}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Подписать школьный контракт сверх лимитов в расчёте на доход кружков. Надлежащий шаг: Увязать обязательство со сметой и лимитами бюджетных обязательств. Основание: БК РФ, статьи 161, 219. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Подписать школьный контракт сверх лимитов в расчёте на доход кружков. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, статьи 161, 219 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":-0.011,"expenditure":50}}]},"comic_scene":{"scene_id":"scene-056","title":"Смета школы","case_key":"bank-legal-2026-006","format":"animated-svg","version":4,"alt":"Смета школы: участники изучают юридический документ и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Смета школы»: Казённая школа Ингушетии принимает обязательство на ремонт сверх доведённых лимитов. Директор обещает закрыть разницу будущей платной кружковой работой.","region_code":"06","region_name":"Республика Ингушетия"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, статьи 161, 219. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-007","title":"Сезонный канат","category":"Региональные финансы","situation":"В Кабардино-Балкарии концессионер канатной дороги требует гарантию доходности на 15 лет. Будущие выплаты не включены в бюджетный прогноз.\n\nВ проекте соглашения есть компенсация недополученной выручки при снижении туристического потока. Сумма может достигнуть 12 млн ₽ в год, но приложение к прогнозу содержит только расходы текущего сезона. Банк считает обещание региона достаточным обеспечением кредита. Участник получил три сценария посещаемости и должен оценить не только первый платёж, но и обязательства будущих периодов.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Оценить долгосрочные обязательства и оформить допустимую концессионную процедуру, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Гарантировать доходность канатной дороги без расчёта будущих выплат, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Оценить долгосрочные обязательства и оформить допустимую концессионную процедуру. Основание: БК РФ, статья 83; Закон № 115-ФЗ. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Оценить долгосрочные обязательства и оформить допустимую концессионную процедуру. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"БК РФ, статья 83; Закон № 115-ФЗ Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.01,"expenditure":21}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статья 83; Закон № 115-ФЗ Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.01,"expenditure":21}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статья 83; Закон № 115-ФЗ Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.01,"expenditure":21}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статья 83; Закон № 115-ФЗ Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.01,"expenditure":21}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Гарантировать доходность канатной дороги без расчёта будущих выплат. Надлежащий шаг: Оценить долгосрочные обязательства и оформить допустимую концессионную процедуру. Основание: БК РФ, статья 83; Закон № 115-ФЗ. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Гарантировать доходность канатной дороги без расчёта будущих выплат. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, статья 83; Закон № 115-ФЗ Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":-0.012,"expenditure":51}}]},"comic_scene":{"scene_id":"scene-057","title":"Сезонный канат","case_key":"bank-legal-2026-007","format":"animated-svg","version":4,"alt":"Сезонный канат: участники изучают инфраструктура и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Сезонный канат»: В Кабардино-Балкарии концессионер канатной дороги требует гарантию доходности на 15 лет. Будущие выплаты не включены в бюджетный прогноз.","region_code":"07","region_name":"Кабардино-Балкарская Республика"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, статья 83; Закон № 115-ФЗ. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-008","title":"Пастбище и кадастр","category":"Региональные финансы","situation":"В Калмыкии земли сельскохозяйственного назначения используют по назначению. Муниципалитет начислил земельный налог по ставке 1,5% без проверки категории.\n\nВ кадастровой выписке указаны категория и разрешённое использование, а акт осмотра подтверждает выпас скота. Налоговое уведомление сформировано по шаблону для иного участка. Собственник просит ответ до срока уплаты и не оспаривает площадь земли. Участнику доступны выписка, муниципальные ставки и расчёт; спор касается правового основания ставки, а не размера дохода хозяйства.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.","seriousness":"serious","audience":"all","allowed_roles":["глава","муницип","министр финансов"],"decision_options":["Проверить категорию и применение специального предела ставки, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Всем сельхозземлям начислить земельный налог 1,5%, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить категорию и применение специального предела ставки. Основание: НК РФ, статья 394. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить категорию и применение специального предела ставки. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"НК РФ, статья 394 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.004,"expenditure":22}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, статья 394 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.004,"expenditure":22}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, статья 394 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.004,"expenditure":22}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, статья 394 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.004,"expenditure":22}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Всем сельхозземлям начислить земельный налог 1,5%. Надлежащий шаг: Проверить категорию и применение специального предела ставки. Основание: НК РФ, статья 394. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Всем сельхозземлям начислить земельный налог 1,5%. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"legal_basis":"НК РФ, статья 394 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":-0.013000000000000001,"expenditure":52}}]},"comic_scene":{"scene_id":"scene-058","title":"Пастбище и кадастр","case_key":"bank-legal-2026-008","format":"animated-svg","version":4,"alt":"Пастбище и кадастр: участники изучают правовой режим земли и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Пастбище и кадастр»: В Калмыкии земли сельскохозяйственного назначения используют по назначению. Муниципалитет начислил земельный налог по ставке 1,5% без проверки категории.","region_code":"08","region_name":"Республика Калмыкия"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. НК РФ, статья 394. https://www.nalog.gov.ru/rn77/taxation/tax_legislation/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-009","title":"Грант родственнику","category":"Региональные финансы","situation":"В Карачаево-Черкесии член комиссии по субсидиям рассматривает заявку фирмы своего брата и участвует в оценивании. Это обнаружено до утверждения протокола.\n\nДве заявки отличаются по оборудованию и плану занятости, а оценочные листы ещё не подписаны. Член комиссии сообщил о родстве только после вопроса секретаря и предложил голосовать «как обычный эксперт». В составе комиссии есть замещающий участник. Нужно определить порядок работы с заявкой, уведомлением и протоколом так, чтобы решение можно было проверить после распределения средств.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Зафиксировать конфликт интересов и исключить участие заинтересованного члена, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Позволить члену комиссии оценить заявку фирмы брата, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Зафиксировать конфликт интересов и исключить участие заинтересованного члена. Основание: Закон № 273-ФЗ, статьи 10–11. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Стратегический критерий: Защита репутации органа через урегулирование конфликта интересов. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Зафиксировать конфликт интересов и исключить участие заинтересованного члена. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":"Защита репутации органа через урегулирование конфликта интересов.","legal_basis":"Закон № 273-ФЗ, статьи 10–11 Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.005,"expenditure":23}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Защита репутации органа через урегулирование конфликта интересов.","legal_basis":"Закон № 273-ФЗ, статьи 10–11 Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.005,"expenditure":23}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Защита репутации органа через урегулирование конфликта интересов.","legal_basis":"Закон № 273-ФЗ, статьи 10–11 Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.005,"expenditure":23}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":"Защита репутации органа через урегулирование конфликта интересов.","legal_basis":"Закон № 273-ФЗ, статьи 10–11 Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.005,"expenditure":23}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Позволить члену комиссии оценить заявку фирмы брата. Надлежащий шаг: Зафиксировать конфликт интересов и исключить участие заинтересованного члена. Основание: Закон № 273-ФЗ, статьи 10–11. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Позволить члену комиссии оценить заявку фирмы брата. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"Закон № 273-ФЗ, статьи 10–11 Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":-0.014,"expenditure":53}}]},"comic_scene":{"scene_id":"scene-059","title":"Грант родственнику","case_key":"bank-legal-2026-009","format":"animated-svg","version":4,"alt":"Грант родственнику: участники изучают правовой режим земли и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Грант родственнику»: В Карачаево-Черкесии член комиссии по субсидиям рассматривает заявку фирмы своего брата и участвует в оценивании. Это обнаружено до утверждения протокола.","region_code":"09","region_name":"Карачаево-Черкесская Республика"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Закон № 273-ФЗ, статьи 10–11. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-010","title":"Лесной доход","category":"Региональные финансы","situation":"В Карелии предлагают оставить в местном бюджете все платежи по аренде лесных участков независимо от принадлежности участка и норм зачисления.\n\nВ учебном реестре есть федеральный лесной участок и участок иной публичной собственности. Проект доходной части объединяет оба договора аренды в одну строку местных поступлений. Финансист намерен направить ожидаемые деньги на освещение поселения. Участнику переданы выписки о собственности и условия аренды; необходимо проверить, какие поступления действительно доступны этому бюджету.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.","seriousness":"serious","audience":"all","allowed_roles":["глава","муницип","министр финансов"],"decision_options":["Разделить виды платежей и применить надлежащие нормативы зачисления, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Оставить все лесные платежи муниципалитету без классификации, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Разделить виды платежей и применить надлежащие нормативы зачисления. Основание: БК РФ, нормы неналоговых доходов. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Разделить виды платежей и применить надлежащие нормативы зачисления. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"БК РФ, нормы неналоговых доходов Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":24}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, нормы неналоговых доходов Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":24}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, нормы неналоговых доходов Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":24}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, нормы неналоговых доходов Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":24}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Оставить все лесные платежи муниципалитету без классификации. Надлежащий шаг: Разделить виды платежей и применить надлежащие нормативы зачисления. Основание: БК РФ, нормы неналоговых доходов. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Оставить все лесные платежи муниципалитету без классификации. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, нормы неналоговых доходов Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":-0.006,"expenditure":54}}]},"comic_scene":{"scene_id":"scene-060","title":"Лесной доход","case_key":"bank-legal-2026-010","format":"animated-svg","version":4,"alt":"Лесной доход: участники изучают правовой режим земли и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Лесной доход»: В Карелии предлагают оставить в местном бюджете все платежи по аренде лесных участков независимо от принадлежности участка и норм зачисления.","region_code":"10","region_name":"Республика Карелия"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, нормы неналоговых доходов. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-011","title":"Северный резерв","category":"Региональные финансы","situation":"В Коми резервный фонд исполнительной власти хотят использовать для ежегодного планового праздника. Непредвиденных обстоятельств не возникло.\n\nПраздник проводится каждый год, дата известна с начала бюджетного планирования. Организатор не получил ассигнования по обычной программе и предлагает провести оплату через резерв. В фонде предусмотрены деньги на внезапные аварии коммунальной инфраструктуры. Участник изучает положение о резервном фонде, заявку и календарь расходов до подготовки распоряжения об использовании средств.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Финансировать плановое мероприятие через предусмотренные бюджетные ассигнования, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Оплатить плановый праздник из резервного фонда как непредвиденный расход, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Финансировать плановое мероприятие через предусмотренные бюджетные ассигнования. Основание: БК РФ, статья 81. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Финансировать плановое мероприятие через предусмотренные бюджетные ассигнования. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"БК РФ, статья 81 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.007,"expenditure":25}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статья 81 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.007,"expenditure":25}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статья 81 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.007,"expenditure":25}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статья 81 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.007,"expenditure":25}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Оплатить плановый праздник из резервного фонда как непредвиденный расход. Надлежащий шаг: Финансировать плановое мероприятие через предусмотренные бюджетные ассигнования. Основание: БК РФ, статья 81. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Оплатить плановый праздник из резервного фонда как непредвиденный расход. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, статья 81 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":-0.007,"expenditure":55}}]},"comic_scene":{"scene_id":"scene-061","title":"Северный резерв","case_key":"bank-legal-2026-011","format":"animated-svg","version":4,"alt":"Северный резерв: участники изучают юридический документ и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Северный резерв»: В Коми резервный фонд исполнительной власти хотят использовать для ежегодного планового праздника. Непредвиденных обстоятельств не возникло.","region_code":"11","region_name":"Республика Коми"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, статья 81. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-012","title":"Цифровое имущество","category":"Региональные финансы","situation":"В Марий Эл бухгалтер включил права на программу для ЭВМ в базу налога на имущество организаций наряду с недвижимостью.\n\nКомпания приобрела офисное здание и исключительное право на программу по разным договорам. В учётной ведомости оба объекта объединены по признаку высокой стоимости. Инспектор просит пояснение о составе налоговой базы за квартал. Участник получает бухгалтерские документы и характеристики активов; решение должно учитывать вид объекта, а не только строку его отражения в общем отчёте.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Разделить объекты учёта и исключить не являющееся объектом налога имущество, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Обложить права на программное обеспечение налогом на недвижимость, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Разделить объекты учёта и исключить не являющееся объектом налога имущество. Основание: НК РФ, статья 374. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Разделить объекты учёта и исключить не являющееся объектом налога имущество. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"НК РФ, статья 374 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.008,"expenditure":26}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, статья 374 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.008,"expenditure":26}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, статья 374 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.008,"expenditure":26}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, статья 374 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.008,"expenditure":26}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Обложить права на программное обеспечение налогом на недвижимость. Надлежащий шаг: Разделить объекты учёта и исключить не являющееся объектом налога имущество. Основание: НК РФ, статья 374. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Обложить права на программное обеспечение налогом на недвижимость. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"НК РФ, статья 374 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":-0.008,"expenditure":56}}]},"comic_scene":{"scene_id":"scene-062","title":"Цифровое имущество","case_key":"bank-legal-2026-012","format":"animated-svg","version":4,"alt":"Цифровое имущество: участники изучают инфраструктура и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Цифровое имущество»: В Марий Эл бухгалтер включил права на программу для ЭВМ в базу налога на имущество организаций наряду с недвижимостью.","region_code":"12","region_name":"Республика Марий Эл"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. НК РФ, статья 374. https://www.nalog.gov.ru/rn77/taxation/tax_legislation/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-013","title":"Спорная дотация","category":"Региональные финансы","situation":"В Мордовии муниципалитет получает дотацию на выравнивание. Региональный чиновник требует вернуть её за несогласованный цвет благоустройства.\n\nДеньги перечислены на выравнивание бюджетной обеспеченности, а не по соглашению о конкретном благоустройстве. Цвет покрытия выбран местным советом в рамках отдельного проекта. Письмо о возврате не содержит расчёта нарушения и ссылки на условие предоставления дотации. Участнику нужно сопоставить назначение трансферта, полномочия сторон и документы требования до ответа финансовому органу.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.","seriousness":"serious","audience":"all","allowed_roles":["глава","муницип","министр финансов"],"decision_options":["Проверить правовой режим дотации и основания бюджетных мер, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Вернуть дотацию только из-за несогласованного цвета благоустройства, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить правовой режим дотации и основания бюджетных мер. Основание: БК РФ, статьи 6, 138. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить правовой режим дотации и основания бюджетных мер. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"БК РФ, статьи 6, 138 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.009000000000000001,"expenditure":27}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статьи 6, 138 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.009000000000000001,"expenditure":27}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статьи 6, 138 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.009000000000000001,"expenditure":27}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статьи 6, 138 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.009000000000000001,"expenditure":27}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Вернуть дотацию только из-за несогласованного цвета благоустройства. Надлежащий шаг: Проверить правовой режим дотации и основания бюджетных мер. Основание: БК РФ, статьи 6, 138. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: глава, муницип, министр финансов. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Вернуть дотацию только из-за несогласованного цвета благоустройства. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["глава","муницип","министр финансов"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, статьи 6, 138 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":-0.009000000000000001,"expenditure":57}}]},"comic_scene":{"scene_id":"scene-063","title":"Спорная дотация","case_key":"bank-legal-2026-013","format":"animated-svg","version":4,"alt":"Спорная дотация: участники изучают бюджетное основание и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Спорная дотация»: В Мордовии муниципалитет получает дотацию на выравнивание. Региональный чиновник требует вернуть её за несогласованный цвет благоустройства.","region_code":"13","region_name":"Республика Мордовия"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, статьи 6, 138. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-014","title":"Тепло на мерзлоте","category":"Региональные финансы","situation":"В Якутии авария теплотрассы требует срочного ремонта. Управление хочет применить закупку у единственного поставщика без описания аварии и объёма срочных работ.\n\nАкт диспетчера фиксирует разрыв трубы и угрозу остановки отопления нескольких домов. Подрядчик готов устранить аварийный участок за 48 часов, но в предложении дополнительно указан плановый ремонт соседней магистрали. Финансирование срочной части определено в резерве. Участник получил фотографии, дефектную ведомость и две сметы; необходимо отделить аварийную потребность от работ, которые могут пройти обычную процедуру.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Документировать аварийные обстоятельства и ограничить закупку необходимым объёмом, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Выбрать единственного подрядчика на все желаемые работы без фиксации аварии, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Документировать аварийные обстоятельства и ограничить закупку необходимым объёмом. Основание: Закон № 44-ФЗ, статья 93. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Документировать аварийные обстоятельства и ограничить закупку необходимым объёмом. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Закон № 44-ФЗ, статья 93 Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.01,"expenditure":28}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Закон № 44-ФЗ, статья 93 Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.01,"expenditure":28}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Закон № 44-ФЗ, статья 93 Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.01,"expenditure":28}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Закон № 44-ФЗ, статья 93 Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.01,"expenditure":28}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Выбрать единственного подрядчика на все желаемые работы без фиксации аварии. Надлежащий шаг: Документировать аварийные обстоятельства и ограничить закупку необходимым объёмом. Основание: Закон № 44-ФЗ, статья 93. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Выбрать единственного подрядчика на все желаемые работы без фиксации аварии. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"Закон № 44-ФЗ, статья 93 Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":-0.01,"expenditure":58}}]},"comic_scene":{"scene_id":"scene-064","title":"Тепло на мерзлоте","case_key":"bank-legal-2026-014","format":"animated-svg","version":4,"alt":"Тепло на мерзлоте: участники изучают целевой объект и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Тепло на мерзлоте»: В Якутии авария теплотрассы требует срочного ремонта. Управление хочет применить закупку у единственного поставщика без описания аварии и объёма срочных работ.","region_code":"14","region_name":"Республика Саха (Якутия)"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Закон № 44-ФЗ, статья 93. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-015","title":"Гарантия футбольному клубу","category":"Региональные финансы","situation":"В Северной Осетии предлагают государственную гарантию по кредиту клуба без анализа финансового состояния принципала и бюджетного оформления.\n\nКлуб просит обеспечение кредита на строительство тренировочной базы сроком на семь лет. В пакете есть презентация посещаемости, но отсутствует проверка финансового положения и обеспечение обратных требований. Предельный объём гарантий в учебном бюджете уже частично занят. Участнику переданы проект гарантии, долговая книга и заявка банка; решение нужно принять до выпуска письма о поддержке.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Проверить условия гарантии, финансовое состояние и бюджетные ограничения, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Выдать гарантию клубу без финансовой проверки и бюджетного оформления, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить условия гарантии, финансовое состояние и бюджетные ограничения. Основание: БК РФ, статьи 115–115.2. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Стратегический критерий: Защита устойчивости казны и границ долговой ответственности. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить условия гарантии, финансовое состояние и бюджетные ограничения. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":"Защита устойчивости казны и границ долговой ответственности.","legal_basis":"БК РФ, статьи 115–115.2 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.004,"expenditure":29}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Защита устойчивости казны и границ долговой ответственности.","legal_basis":"БК РФ, статьи 115–115.2 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.004,"expenditure":29}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Защита устойчивости казны и границ долговой ответственности.","legal_basis":"БК РФ, статьи 115–115.2 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.004,"expenditure":29}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":"Защита устойчивости казны и границ долговой ответственности.","legal_basis":"БК РФ, статьи 115–115.2 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.004,"expenditure":29}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Выдать гарантию клубу без финансовой проверки и бюджетного оформления. Надлежащий шаг: Проверить условия гарантии, финансовое состояние и бюджетные ограничения. Основание: БК РФ, статьи 115–115.2. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Выдать гарантию клубу без финансовой проверки и бюджетного оформления. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, статьи 115–115.2 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":-0.011,"expenditure":59}}]},"comic_scene":{"scene_id":"scene-065","title":"Гарантия футбольному клубу","case_key":"bank-legal-2026-015","format":"animated-svg","version":4,"alt":"Гарантия футбольному клубу: участники изучают основание решения и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Гарантия футбольному клубу»: В Северной Осетии предлагают государственную гарантию по кредиту клуба без анализа финансового состояния принципала и бюджетного оформления.","region_code":"15","region_name":"Республика Северная Осетия — Алания"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, статьи 115–115.2. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-016","title":"Платёж за станок","category":"Региональные финансы","situation":"В Татарстане промышленная субсидия возмещает покупку оборудования. Заявитель представил один и тот же счёт для двух программ возмещения.\n\nОба отчёта относятся к одному станку, одной накладной и одной дате оплаты. Первая программа покрывает часть покупки, вторая рассчитана на другой набор подтверждённых затрат. Получатель считает, что разные названия программ допускают повторное возмещение. Участник проверяет соглашения и документы об оплате до утверждения суммы; отдельный вопрос — корректность уже представленного отчёта.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Проверить недопустимость двойного возмещения и фактические затраты, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Возместить один станок дважды из разных программ, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить недопустимость двойного возмещения и фактические затраты. Основание: БК РФ, статья 78. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить недопустимость двойного возмещения и фактические затраты. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"БК РФ, статья 78 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.005,"expenditure":30}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статья 78 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.005,"expenditure":30}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статья 78 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.005,"expenditure":30}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статья 78 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.005,"expenditure":30}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Возместить один станок дважды из разных программ. Надлежащий шаг: Проверить недопустимость двойного возмещения и фактические затраты. Основание: БК РФ, статья 78. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Возместить один станок дважды из разных программ. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, статья 78 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":-0.012,"expenditure":60}}]},"comic_scene":{"scene_id":"scene-066","title":"Платёж за станок","case_key":"bank-legal-2026-016","format":"animated-svg","version":4,"alt":"Платёж за станок: участники изучают текст и права и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Платёж за станок»: В Татарстане промышленная субсидия возмещает покупку оборудования. Заявитель представил один и тот же счёт для двух программ возмещения.","region_code":"16","region_name":"Республика Татарстан"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, статья 78. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-017","title":"Дорога в долг","category":"Региональные финансы","situation":"В Тыве банк предлагает кредит, после которого плановый долг превысит допустимый для конкретного региона предел. Ответственный сравнил только процентную ставку.\n\nВ таблице заимствований не учтены два действующих обязательства, а доходная база включает целевые поступления. Кредит дешевле альтернативы на один процентный пункт, но требует погашения в следующем году. Финансовый орган должен представить расчёт допустимого объёма долга на заседании. Участнику доступны долговая книга и проект доходов; выбрать действие нужно до подписания кредитного договора.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Рассчитать объём долга и соблюдение применимых ограничений до заимствования, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Взять кредит без расчёта установленного предела долга, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Рассчитать объём долга и соблюдение применимых ограничений до заимствования. Основание: БК РФ, статьи 106–107. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Рассчитать объём долга и соблюдение применимых ограничений до заимствования. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"БК РФ, статьи 106–107 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":31}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статьи 106–107 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":31}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статьи 106–107 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":31}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статьи 106–107 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":31}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Взять кредит без расчёта установленного предела долга. Надлежащий шаг: Рассчитать объём долга и соблюдение применимых ограничений до заимствования. Основание: БК РФ, статьи 106–107. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Взять кредит без расчёта установленного предела долга. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, статьи 106–107 Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":-0.013000000000000001,"expenditure":61}}]},"comic_scene":{"scene_id":"scene-067","title":"Дорога в долг","case_key":"bank-legal-2026-017","format":"animated-svg","version":4,"alt":"Дорога в долг: участники изучают основание решения и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Дорога в долг»: В Тыве банк предлагает кредит, после которого плановый долг превысит допустимый для конкретного региона предел. Ответственный сравнил только процентную ставку.","region_code":"17","region_name":"Республика Тыва"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, статьи 106–107. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-018","title":"Оружейный заказ","category":"Региональные финансы","situation":"В Удмуртии открытый конкурс на поставку содержит сведения ограниченного доступа. Заказчик намерен опубликовать весь технический пакет вместе с извещением.\n\nПоставщик прислал техническое приложение, часть которого отмечена как сведения ограниченного доступа. Электронная площадка предлагает общий режим размещения файлов. Сотрудник закупок хочет ускорить публикацию, чтобы не сорвать производственный график. Участник получил отметки о режиме информации и проект документации; необходимо определить процедуру и состав раскрываемых сведений до отправки извещения.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Отделить защищённые сведения и выбрать надлежащую процедуру закупки, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Раскрыть все сведения оборонного заказа в открытой закупке, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Отделить защищённые сведения и выбрать надлежащую процедуру закупки. Основание: Закон № 44-ФЗ, специальные закрытые процедуры. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Отделить защищённые сведения и выбрать надлежащую процедуру закупки. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Закон № 44-ФЗ, специальные закрытые процедуры Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.007,"expenditure":15}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Закон № 44-ФЗ, специальные закрытые процедуры Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.007,"expenditure":15}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Закон № 44-ФЗ, специальные закрытые процедуры Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.007,"expenditure":15}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Закон № 44-ФЗ, специальные закрытые процедуры Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.007,"expenditure":15}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Раскрыть все сведения оборонного заказа в открытой закупке. Надлежащий шаг: Отделить защищённые сведения и выбрать надлежащую процедуру закупки. Основание: Закон № 44-ФЗ, специальные закрытые процедуры. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Раскрыть все сведения оборонного заказа в открытой закупке. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"Закон № 44-ФЗ, специальные закрытые процедуры Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":-0.014,"expenditure":62}}]},"comic_scene":{"scene_id":"scene-068","title":"Оружейный заказ","case_key":"bank-legal-2026-018","format":"animated-svg","version":4,"alt":"Оружейный заказ: участники изучают поставка и приёмка и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Оружейный заказ»: В Удмуртии открытый конкурс на поставку содержит сведения ограниченного доступа. Заказчик намерен опубликовать весь технический пакет вместе с извещением.","region_code":"18","region_name":"Удмуртская Республика"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Закон № 44-ФЗ, специальные закрытые процедуры. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-019","title":"Угольный вычет","category":"Региональные финансы","situation":"В Хакасии предприятие просит уменьшить НДПИ на расходы, не подтверждённые документами и не относящиеся к предусмотренному вычету.\n\nПредприятие предъявило платежи за ремонт административного здания вместе с расходами производственного участка. Документы о назначении затрат представлены не полностью. В декларации уже рассчитана сумма предполагаемого уменьшения налога. Участнику доступны счета, акты и перечень заявленных расходов; решение требуется до подачи уточнений, с проверкой связи каждой суммы с установленными условиями вычета.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Проверить условия вычета и документальную связь расходов, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Применить угольный вычет без проверки вида расходов и условий, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить условия вычета и документальную связь расходов. Основание: НК РФ, глава 26. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить условия вычета и документальную связь расходов. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"НК РФ, глава 26 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.008,"expenditure":16}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, глава 26 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.008,"expenditure":16}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, глава 26 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.008,"expenditure":16}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, глава 26 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.008,"expenditure":16}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Применить угольный вычет без проверки вида расходов и условий. Надлежащий шаг: Проверить условия вычета и документальную связь расходов. Основание: НК РФ, глава 26. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Применить угольный вычет без проверки вида расходов и условий. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"НК РФ, глава 26 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":-0.006,"expenditure":63}}]},"comic_scene":{"scene_id":"scene-069","title":"Угольный вычет","case_key":"bank-legal-2026-019","format":"animated-svg","version":4,"alt":"Угольный вычет: участники изучают юридический документ и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Угольный вычет»: В Хакасии предприятие просит уменьшить НДПИ на расходы, не подтверждённые документами и не относящиеся к предусмотренному вычету.","region_code":"19","region_name":"Республика Хакасия"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. НК РФ, глава 26. https://www.nalog.gov.ru/rn77/taxation/tax_legislation/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-020","title":"Кассовый разрыв","category":"Региональные финансы","situation":"В Чечне временно не хватает денег на уже предусмотренные обязательства. Участник называет кассовый разрыв новым дефицитом бюджета и предлагает отменить все расходы.\n\nКассовый план показывает поступление доходов через десять дней, тогда как зарплата и договорные платежи должны пройти на этой неделе. Годовые ассигнования и ожидаемые доходы не изменились. В служебной записке смешаны остаток денег на счёте и годовой баланс. Участник должен выбрать порядок исполнения обязательств на коротком горизонте, используя кассовый план, платёжный календарь и условия допустимого финансирования.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Разделить временную ликвидность и годовой дефицит, выбрать допустимое финансирование, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Закрыть кассовый разрыв обещанием поступлений без законного инструмента, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Разделить временную ликвидность и годовой дефицит, выбрать допустимое финансирование. Основание: БК РФ, исполнение бюджета. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Разделить временную ликвидность и годовой дефицит, выбрать допустимое финансирование. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"БК РФ, исполнение бюджета Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.009000000000000001,"expenditure":17}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, исполнение бюджета Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.009000000000000001,"expenditure":17}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, исполнение бюджета Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.009000000000000001,"expenditure":17}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, исполнение бюджета Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.009000000000000001,"expenditure":17}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Закрыть кассовый разрыв обещанием поступлений без законного инструмента. Надлежащий шаг: Разделить временную ликвидность и годовой дефицит, выбрать допустимое финансирование. Основание: БК РФ, исполнение бюджета. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Закрыть кассовый разрыв обещанием поступлений без законного инструмента. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, исполнение бюджета Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":-0.007,"expenditure":64}}]},"comic_scene":{"scene_id":"scene-070","title":"Кассовый разрыв","case_key":"bank-legal-2026-020","format":"animated-svg","version":4,"alt":"Кассовый разрыв: участники изучают правовой режим земли и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Кассовый разрыв»: В Чечне временно не хватает денег на уже предусмотренные обязательства. Участник называет кассовый разрыв новым дефицитом бюджета и предлагает отменить все расходы.","region_code":"20","region_name":"Чеченская Республика"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, исполнение бюджета. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-021","title":"Экспортный аванс","category":"Региональные финансы","situation":"В Чувашии завод получил аванс от иностранного покупателя. Бухгалтер автоматически применил нулевой НДС ко всем внутренним продажам этого месяца.\n\nВ одном месяце завод реализовал продукцию за рубеж и покупателям внутри страны. Экспортный комплект подтверждений ещё собирается, но бухгалтер перенёс одну ставку на весь журнал продаж. Покупатель внутренней партии просит корректный счёт-фактуру. Участник получает договоры, отгрузочные документы и реестр аванса; важны вид операции и её подтверждение, а не валюта отдельного поступления.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Разделить операции и подтверждение права на нулевую ставку, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Вернуть НДС по неподтверждённому экспортному авансу, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Разделить операции и подтверждение права на нулевую ставку. Основание: НК РФ, статьи 164–165. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Разделить операции и подтверждение права на нулевую ставку. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"НК РФ, статьи 164–165 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.01,"expenditure":18}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, статьи 164–165 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.01,"expenditure":18}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, статьи 164–165 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.01,"expenditure":18}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"НК РФ, статьи 164–165 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.01,"expenditure":18}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Вернуть НДС по неподтверждённому экспортному авансу. Надлежащий шаг: Разделить операции и подтверждение права на нулевую ставку. Основание: НК РФ, статьи 164–165. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Вернуть НДС по неподтверждённому экспортному авансу. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"НК РФ, статьи 164–165 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":-0.008,"expenditure":65}}]},"comic_scene":{"scene_id":"scene-071","title":"Экспортный аванс","case_key":"bank-legal-2026-021","format":"animated-svg","version":4,"alt":"Экспортный аванс: участники изучают целевой объект и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Экспортный аванс»: В Чувашии завод получил аванс от иностранного покупателя. Бухгалтер автоматически применил нулевой НДС ко всем внутренним продажам этого месяца.","region_code":"21","region_name":"Чувашская Республика"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. НК РФ, статьи 164–165. https://www.nalog.gov.ru/rn77/taxation/tax_legislation/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-022","title":"Агростраховой платёж","category":"Региональные финансы","situation":"В Алтайском крае возмещение агростраховых затрат заявляет хозяйство без действующего договора страхования. Оно предлагает позже донести полис.\n\nХозяйство представило расчёт затрат и письмо страхового агента, но договор ещё не вступил в силу. В регионе начинается посевная, и фермер просит аванс на семена. Порядок поддержки содержит перечень подтверждающих документов и срок подачи. Участник должен решить, какой пакет можно принять сейчас, опираясь на фактические расходы и условия программы, до перечисления бюджетных средств.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Проверить обязательные условия поддержки до признания расходов допустимыми, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Считать страхование урожая безусловным правом на любое возмещение, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Проверить обязательные условия поддержки до признания расходов допустимыми. Основание: БК РФ, статья 78; Закон № 260-ФЗ. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Проверить обязательные условия поддержки до признания расходов допустимыми. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"БК РФ, статья 78; Закон № 260-ФЗ Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.004,"expenditure":19}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статья 78; Закон № 260-ФЗ Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.004,"expenditure":19}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статья 78; Закон № 260-ФЗ Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.004,"expenditure":19}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, статья 78; Закон № 260-ФЗ Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.004,"expenditure":19}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Считать страхование урожая безусловным правом на любое возмещение. Надлежащий шаг: Проверить обязательные условия поддержки до признания расходов допустимыми. Основание: БК РФ, статья 78; Закон № 260-ФЗ. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Считать страхование урожая безусловным правом на любое возмещение. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, статья 78; Закон № 260-ФЗ Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":-0.009000000000000001,"expenditure":66}}]},"comic_scene":{"scene_id":"scene-072","title":"Агростраховой платёж","case_key":"bank-legal-2026-022","format":"animated-svg","version":4,"alt":"Агростраховой платёж: участники изучают обязательства сторон и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Агростраховой платёж»: В Алтайском крае возмещение агростраховых затрат заявляет хозяйство без действующего договора страхования. Оно предлагает позже донести полис.","region_code":"22","region_name":"Алтайский край"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, статья 78; Закон № 260-ФЗ. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-023","title":"Пляжная плата","category":"Региональные финансы","situation":"В Краснодарском крае администрация вводит обязательный сбор за проход к общедоступному берегу, называя его неналоговым доходом бюджета.\n\nНа входе установлена будка оплаты, а альтернативный проход перекрыт ограждением арендатора. Местный бюджет планирует получить 1,8 млн ₽ за сезон. В проекте акта термин «услуга» применяется к самому проходу, без отдельной услуги посетителю. Участнику переданы схема берега, договор аренды и проект решения; нужно проверить правовую природу платежа и доступ граждан.\n\nОграничения ресурсов. На подготовку ответа отведено двое суток, а финансовое решение должно быть увязано с утверждёнными лимитами и действующими обязательствами. Ускоренное согласование может сократить ожидание граждан, однако создаёт риск ошибок в смете, распределении ответственности либо выборе исполнителя. Напротив, проведение всех проверок без установленного графика может сорвать сроки. Доступные решения должны учитывать обе стороны этого противоречия.\n\nДля предметной оценки требуется соотнести сведения из обращения с действующими полномочиями профильного ведомства, определить ответственного исполнителя и указать документ, которым будет оформлен результат. Указание на срочность обращения не заменяет правового основания.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Сохранить предусмотренный законом доступ и проверить законность платежа, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Объявить вход на публичный пляж новым местным налогом, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Сохранить предусмотренный законом доступ и проверить законность платежа. Основание: Водный кодекс РФ, статья 6. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Сохранить предусмотренный законом доступ и проверить законность платежа. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"Водный кодекс РФ, статья 6 Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.005,"expenditure":20}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Водный кодекс РФ, статья 6 Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.005,"expenditure":20}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Водный кодекс РФ, статья 6 Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.005,"expenditure":20}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"Водный кодекс РФ, статья 6 Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":0.005,"expenditure":20}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Объявить вход на публичный пляж новым местным налогом. Надлежащий шаг: Сохранить предусмотренный законом доступ и проверить законность платежа. Основание: Водный кодекс РФ, статья 6. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Объявить вход на публичный пляж новым местным налогом. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"Водный кодекс РФ, статья 6 Источник: https://pravo.gov.ru/","fiscal_effect":{"activity":-0.01,"expenditure":67}}]},"comic_scene":{"scene_id":"scene-073","title":"Пляжная плата","case_key":"bank-legal-2026-023","format":"animated-svg","version":4,"alt":"Пляжная плата: участники изучают целевой объект и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Пляжная плата»: В Краснодарском крае администрация вводит обязательный сбор за проход к общедоступному берегу, называя его неналоговым доходом бюджета.","region_code":"23","region_name":"Краснодарский край"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. Водный кодекс РФ, статья 6. https://pravo.gov.ru/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-024","title":"Нефтяная цена","category":"Региональные финансы","situation":"Красноярский край включил разовое поступление от продажи имущества в постоянную базу финансирования зарплат. Следующие три года продажи не ожидается.\n\nПродажа склада даст учебному бюджету 140 млн ₽ в первом году. В расходном плане на эту сумму назначены постоянные выплаты, а повторного имущества для продажи нет. При ухудшении доходов обязательства по зарплате сохранятся. Участник получил трёхлетний прогноз и ведомость имущества; решение требует сопоставить устойчивость источника с характером финансируемого расхода.\n\nИнтересы сторон. Представители населения требуют понятных сроков и открытой информации; профильная организация заинтересована в непрерывности своей работы; финансовый орган предупреждает о последствиях новых расходов. Между этими позициями нет автоматического совпадения. Необходимо предложить вариант, который позволяет проверить результаты, не обещает заранее недоступные ресурсы и сохраняет возможность исправить решение при поступлении новых сведений.\n\nВ пределах одного бюджетного периода ответственным подразделениям предстоит согласовать приоритеты, не ухудшая исполнение действующих обязательств. Даже небольшое изменение порядка финансирования требует проверки компетенции инициатора и допустимых источников.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Разделить разовые доходы и устойчивые источники постоянных обязательств, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Признать фиксированную нефтяную цену гарантированным бюджетным доходом, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Разделить разовые доходы и устойчивые источники постоянных обязательств. Основание: БК РФ, принципы достоверности и сбалансированности. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Разделить разовые доходы и устойчивые источники постоянных обязательств. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":null,"legal_basis":"БК РФ, принципы достоверности и сбалансированности Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":21}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, принципы достоверности и сбалансированности Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":21}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, принципы достоверности и сбалансированности Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":21}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":null,"legal_basis":"БК РФ, принципы достоверности и сбалансированности Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":0.006,"expenditure":21}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Признать фиксированную нефтяную цену гарантированным бюджетным доходом. Надлежащий шаг: Разделить разовые доходы и устойчивые источники постоянных обязательств. Основание: БК РФ, принципы достоверности и сбалансированности. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Признать фиксированную нефтяную цену гарантированным бюджетным доходом. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"БК РФ, принципы достоверности и сбалансированности Источник: https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721","fiscal_effect":{"activity":-0.011,"expenditure":68}}]},"comic_scene":{"scene_id":"scene-074","title":"Нефтяная цена","case_key":"bank-legal-2026-024","format":"animated-svg","version":4,"alt":"Нефтяная цена: участники изучают юридический документ и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Нефтяная цена»: Красноярский край включил разовое поступление от продажи имущества в постоянную базу финансирования зарплат. Следующие три года продажи не ожидается.","region_code":"24","region_name":"Красноярский край"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. БК РФ, принципы достоверности и сбалансированности. https://pravo.gov.ru/proxy/ips/?docbody=&nd=102054721 Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."},{"case_key":"bank-legal-2026-025","title":"Портовая льгота","category":"Региональные финансы","situation":"В Приморском крае инвестору обещано освобождение от всех федеральных налогов региональным соглашением. Заявитель просит заверить обещание печатью.\n\nИнвестор планирует склад и просит приложить письмо администрации к кредитному досье. В перечне обещанных льгот смешаны федеральные и региональные платежи. Опубликованного основания для части обещаний нет, но презентация уже распространяется среди партнёров. Участник сопоставляет соглашение и полномочия публичного органа до заверения документа; коммерческий эффект обещания не заменяет его правовое основание.\n\nДокументы и контроль. В материалах имеется первоначальное обращение, проект служебной записки и предварительная оценка последствий, но окончательный акт ещё не принят. Исполнители спорят, достаточно ли этих сведений для перехода к следующей процедуре. Рассматривая альтернативы, сопоставьте правовое основание, уровень компетенции, проверяемость данных, финансовые ограничения и порядок информирования заинтересованных сторон. Формальное выполнение одного из требований само по себе не гарантирует наилучшего результата.\n\nЮридическая служба предупреждает, что организационная целесообразность и наличие полномочия являются разными вопросами. Документ, подписанный ненадлежащим субъектом, может быть оспорен независимо от практической полезности меры.\n\nРазвилка. При выборе решения учитывайте, что промедление тоже влияет на права и интересы людей. Вместе с тем срочность не отменяет разграничения полномочий, специальных процедур и обязательной проверки основания расхода. Наибольшую ценность имеет управленческая последовательность, которую реально исполнить в указанный срок и документально подтвердить. Решение принимается сейчас, до поступления окончательных результатов проверки.\n\nПолитико-административный эффект. Действия ведомства будут оценивать не только непосредственные получатели услуги, но и другие органы власти, которым затем потребуется исполнять принятое решение. Непрозрачное распределение ресурсов может создать прецедент для аналогичных обращений, а необъяснённый отказ — увеличить число жалоб. Поэтому важно отделить краткосрочное снижение напряжённости от долгосрочной устойчивости выбранного механизма и соблюдения установленной процедуры.\n\nУправленческий контекст. Заявители ожидают определённого решения именно по представленным обстоятельствам, но само наличие общественного запроса ещё не устанавливает компетенцию федерального органа. Для правомерного действия важно различать подготовку предложения, согласование проекта, утверждение расходного обязательства и исполнение уже принятого решения. Должностное лицо располагает сведениями из обращения, однако не вправе подменять ими обязательные процедуры и проверки.\n\nРаспределение ответственности. Ведомство отвечает за направление государственной политики и межведомственную координацию, тогда как конкретные имущественные, бюджетные и организационные действия могут относиться к полномочиям другого уровня публичной власти. Региональная администрация, профильное учреждение и федеральное министерство заинтересованы в оперативном результате, но их возможности различаются. Следует определить, кто вправе подписать итоговый документ, кто предоставляет заключение и кто контролирует исполнение.","seriousness":"serious","audience":"all","allowed_roles":["министр финансов","правительств","губернатор"],"decision_options":["Указать только предусмотренные законом льготы и пределы региональной компетенции, с указанием ответственного органа, документа и срока контроля исполнения","Организовать проверку компетенции и исходных данных, затем внести вопрос на согласование, не принимая окончательного решения до заключения","Согласовать с заинтересованными органами поэтапное исполнение и временные меры, оставив окончательные финансовые обязательства до отдельного решения","Оформить предварительное ведомственное решение в пределах имеющихся полномочий и передать его на последующее утверждение с контрольным сроком","Распространить портовую льготу на деятельность вне её условий, предусмотрев ведомственный мониторинг и последующее документальное уточнение оснований"],"effect_plan":{"options":[{"key":"option_1","trust":1,"description":"Указать только предусмотренные законом льготы и пределы региональной компетенции. Основание: НК РФ, статьи 12, 56. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Стратегический критерий: Поддержка портового инвестора в пределах законных льгот. Решение предусматривает исполнителя, правовое оформление и проверяемый результат.","news":"Указать только предусмотренные законом льготы и пределы региональной компетенции. В учебной модели устранён конкретный правовой риск. Проверено соблюдение процедуры.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":true,"role_interest_note":"Поддержка портового инвестора в пределах законных льгот.","legal_basis":"НК РФ, статьи 12, 56 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.007,"expenditure":22}},{"key":"option_2","trust":0,"description":"Процедура остаётся правомерной, однако принятие результата откладывается до дополнительной экспертизы, что может повлиять на установленные сроки.","news":"Ведомство перенесло окончательное решение для дополнительной проверки.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Поддержка портового инвестора в пределах законных льгот.","legal_basis":"НК РФ, статьи 12, 56 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.007,"expenditure":22}},{"key":"option_3","trust":0,"description":"Разделение работы между ведомствами может улучшить согласование, но без утверждённого распределения компетенций и финансирования окончательная задача не решена.","news":"Участники согласовали последовательность действий без окончательного решения.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":true,"protects_role_interest":false,"role_interest_note":"Поддержка портового инвестора в пределах законных льгот.","legal_basis":"НК РФ, статьи 12, 56 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.007,"expenditure":22}},{"key":"option_4","trust":-1,"description":"Формальное промежуточное оформление не заменяет необходимой процедуры принятия окончательного акта, если само решение затрагивает полномочия другого органа.","news":"Промежуточный акт потребовал дополнительной проверки полномочий.","public_interest":"beneficial","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"role_interest_note":"Поддержка портового инвестора в пределах законных льгот.","legal_basis":"НК РФ, статьи 12, 56 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":0.007,"expenditure":22}},{"key":"option_5","trust":-2,"description":"Выбранный способ не устраняет нарушение: Распространить портовую льготу на деятельность вне её условий. Надлежащий шаг: Указать только предусмотренные законом льготы и пределы региональной компетенции. Основание: НК РФ, статьи 12, 56. Выполнить этот шаг следует в установленной процедуре и в пределах компетенции: министр финансов, правительств, губернатор. При отсутствии нужной игровой должности необходимо было пригласить уполномоченного участника до голосования. Предложенный последующий контроль не устраняет первоначального недостатка правового основания.","news":"Выбран спорный способ: Распространить портовую льготу на деятельность вне её условий. Возник риск законности и доверия. Дополнительный мониторинг не устранил процедурный риск.","public_interest":"harmful","authorized_roles":["министр финансов","правительств","губернатор"],"lawful":false,"protects_role_interest":false,"legal_basis":"НК РФ, статьи 12, 56 Источник: https://www.nalog.gov.ru/rn77/taxation/tax_legislation/","fiscal_effect":{"activity":-0.012,"expenditure":69}}]},"comic_scene":{"scene_id":"scene-075","title":"Портовая льгота","case_key":"bank-legal-2026-025","format":"animated-svg","version":4,"alt":"Портовая льгота: участники изучают бюджетное основание и документы по ситуации.","media_label":"Бюджетный обозреватель","news_lead":"Ситуация «Портовая льгота»: В Приморском крае инвестору обещано освобождение от всех федеральных налогов региональным соглашением. Заявитель просит заверить обещание печатью.","region_code":"25","region_name":"Приморский край"},"source_note":"Авторская учебная задача на основе норм российского права; факты вымышлены. НК РФ, статьи 12, 56. https://www.nalog.gov.ru/rn77/taxation/tax_legislation/ Последствия в рейтингах и бюджете — игровые допущения. Подлежит обсуждению и проверке преподавателем."}]$authored$::jsonb))
INSERT INTO private.authored_event_catalog(case_key,content)
SELECT doc->>'case_key',doc FROM docs ON CONFLICT(case_key) DO UPDATE SET content=excluded.content;
UPDATE public.event_cases e SET situation=c.content->>'situation',decision_options=c.content->'decision_options',effect_plan=c.content->'effect_plan',allowed_roles=ARRAY(SELECT jsonb_array_elements_text(c.content->'allowed_roles'))
FROM private.authored_event_catalog c WHERE e.case_key=c.case_key AND e.case_key IN ('bank-legal-2026-001','bank-legal-2026-002','bank-legal-2026-003','bank-legal-2026-004','bank-legal-2026-005','bank-legal-2026-006','bank-legal-2026-007','bank-legal-2026-008','bank-legal-2026-009','bank-legal-2026-010','bank-legal-2026-011','bank-legal-2026-012','bank-legal-2026-013','bank-legal-2026-014','bank-legal-2026-015','bank-legal-2026-016','bank-legal-2026-017','bank-legal-2026-018','bank-legal-2026-019','bank-legal-2026-020','bank-legal-2026-021','bank-legal-2026-022','bank-legal-2026-023','bank-legal-2026-024','bank-legal-2026-025')
AND NOT EXISTS(SELECT 1 FROM public.event_assignments a WHERE a.case_id=e.id)
AND NOT EXISTS(SELECT 1 FROM public.event_decisions d WHERE d.case_id=e.id)
AND NOT EXISTS(SELECT 1 FROM public.event_case_outcomes o WHERE o.case_id=e.id);
